use super::{ffi,DirectEditor};use notepad_core::LineColour;use crate::theme::Rgba;
pub fn slot(c:LineColour)->Option<usize>{match c{LineColour::None=>None,LineColour::Yellow=>Some(0),LineColour::Green=>Some(1),LineColour::Pink=>Some(2),LineColour::Blue=>Some(3),LineColour::Orange=>Some(4),LineColour::Purple=>Some(5),LineColour::Custom(v)=>Some(6+(v as usize%2))}}pub fn configure(editor:&DirectEditor){for i in 0..8{editor.send(ffi::SCI_INDICSETSTYLE,i,ffi::INDIC_FULLBOX as isize);editor.send(ffi::SCI_INDICSETALPHA,i,64);editor.send(ffi::SCI_INDICSETOUTLINEALPHA,i,128)}for c in LineColour::BUILT_INS{if let(Some(i),Some(v))=(slot(c),c.rgb()){editor.send(ffi::SCI_INDICSETFORE,i,ffi::rgb(v)as isize)}}}pub fn apply_line(editor:&DirectEditor,line:usize,c:LineColour){if let Some(i)=slot(c){let s=editor.line_start(line);let n=editor.line_length(line);if n>0{editor.set_indicator_range(i,s,n)}}}pub fn rgba(c:Rgba)->isize{((c.r as u32)<<16|((c.g as u32)<<8)|c.b as u32)as isize}
